resources.string:
        {
    "Old": [
        {
            "C": [
                {
                    "Vs": [
                        {
                            "V": "ஆதியிலே கடவுள் விண்ணையும், மண்ணையும் படைத்தார்"
                        },
                        {
                            "V": "பூமி உருவமற்றதும் வெறுமையுற்றதுமாய் இருந்தது.  பாதாளத்தின் முகத்தே இருள் பரவியிருந்தது.  கடவுளின் ஆவியானவர் தண்ணீரின் மீது அசைவாடிக் கொண்டிருந்தார்."
                        },
                        {
                            "V": "அப்பொழுது கடவுள்: ஒளி உண்டாகுக என்று உரைத்தார்.  உரைக்கவே, ஒளி உண்டாயிற்று."
                        },
                        {
                            "V": "கடவுள் ஒளியை நல்லது என்று கண்டு, ஒளியை இருளினின்று பிரித்தார்."
                        },
                        {
                            "V": "ஒளிக்குப் பகல் என்றும், இருளுக்கு இரவு என்றும் பெயரிட்டார்.  மாலையும் காலையும் சேர்ந்து முதல் நாள் ஆயிற்று."
                        },
                        {
                            "V": "பின் கடவுள்: நீர்த்திரளின் நடுவில் வானவெளி உண்டாகி நீரினின்று நீர் பிரியக் கடவது என்றார்."
                        },
                        {
                            "V": "இவ்வாறு கடவுள் வான வெளியை உண்டாக்கி, வானவெளிக்குக் கீழேயுள்ள நீரையும், வானவெளிக்கு மேலேயுள்ள நீரையும் பிரித்தார்.  அதுவும் அவ்வண்ணமே ஆயிற்று"
                        },
                        {
                            "V": "கடவுள் வானவெளிக்குப் பரலோகம் என்று பெயரிட்டார்.  மாலையும் காலையும் சேர்ந்து இரண்டாம் நாள் ஆயிற்று."
                        },
                        {
                            "V": "மேலும் கடவுள்: வானவெளிக்குக் கீழேயுள்ள நீரெல்லாம் ஒரே இடத்தில் ஒன்றாகச் சேரக்கடவது; காய்ந்த தரை தோன்றக்கடவது என்றார்.  அது அப்படியே ஆயிற்று."
                        },
                        {
                            "V": "காய்ந்த தரைக்கு நிலம் என்றும், ஒன்றாகச் சேர்ந்த நீர்த்திரளுக்குக் கடல் என்றும்  கடவுள் பெயரிட்டார்.  அதுவும் நலமென்று கடவுள் கண்டார்."
                        },
                        {
                            "V": "அப்போது அவர்: விதையைப் பிறப்பிக்கும் பசும் புற்பூண்டுகளையும், பூமியின் மீது தம்மிடம் விதைகளைக் கொண்டுள்ள கனிகளைத் தத்தம் இனத்தின்படியே தரும் மரங்களையும் பூமி முளைப்பிக்கக்கடவது என்றார்."
                        },
                        {
                            "V": "அதுவும் அப்படியே ஆயிற்று.  பூமி தத்தம் இனத்தின்படியே தத்தம் விதையைப் பிறப்பிக்கும் புற்பூண்டுகளையும், தத்தம் இனத்தின்படி தம்மிடம் விதைகளைக் கொண்டுள்ள மரங்களையும் முளைப்பித்தது.  கடவுள் அதுவும் நல்லதென்று கண்டார்."
                        },
                        {
                            "V": "மாலையும் காலையும் சேர்ந்து மூன்றாம் நாள் ஆயிற்று."
                        },
                        {
                            "V": "மேலும் கடவுள்: பரமண்டல வான்வெளியில் சுடர்கள் உண்டாகிப் பகலையும் இரவையும் பிரிக்கக் கடவன; அவை பருவக் காலங்களையும் நாட்களையும் ஆண்டுகளையும் குறிப்பதற்கான அடையாளங்களாய் அமையக் கடவன."
                        },
                        {
                            "V": "அவை பரமண்டல வான்வெளியில் சுடர்களாய் இருந்து பூமிக்கு ஒளி தரக்கடவன என்றார்.  அதுவும் அப்படியே ஆயிற்று."
                        },
                        {
                            "V": "அப்போது கடவுள் பகலை ஆளப் பெரியதொரு சுடரும், இரவை ஆளச் சிறியதொரு சுடருமாக இரு பெரும் சுடர்களையும் விண்மீன்களையும் உண்டாக்கினார்."
                        },
                        {
                            "V": "கடவுள் அவற்றைப் பரமண்டல வானவெளியில் நிறுவிப் பூமியின் மேல் ஒளி வீசவும்,"
                        },
                        {
                            "V": "பகலையும் இரவையும் ஆளவும், ஒளியையும் இருளையும் பிரிக்கவும் அமைத்தார்.  கடவுள் அதுவும் நல்லதென்று கண்டார்."
                        },
                        {
                            "V": "மாலையும் காலையும் சேர்ந்து நான்காம் நாள் ஆயிற்று."
                        },
                        {
                            "V": "மேலும் கடவுள்: அசைந்து உலாவும் உயிரினங்களையும், பூமியின் மேலே பரமண்டல வான்வெளியில் பறந்து திரியும் பறவைகளையும், நீர்த்திரள் பிறப்பிக்கக்கடவது என்றார்."
                        },
                        {
                            "V": "அப்போது கடவுள் திமிங்கிலங்களையும், உயிரும் அசைவும் உடையனவாய் நீர்திரளில் உற்பத்தியாகிய வகை வகையான பிராணிகள், வித விதமான பறவைகள் எல்லாவற்றையும் படைத்தார்.  கடவுள் அதுவும் நல்லதென்று கண்டர்."
                        },
                        {
                            "V": "அவர் அவைகளை ஆசீர்வதித்து: நீங்கள் பலுகிப் பெருகிக் கடல் நீரை நிரப்புங்கள்; பறவைகளும் பூமியில் பலுகக் கடவன என்றார்."
                        },
                        {
                            "V": "மாலையும் காலையும் சேர்ந்து ஐந்தாம் நாள் ஆயிற்று."
                        },
                        {
                            "V": "பின் கடவுள்: பலவகையான உயிரினங்களையும், வீட்டு விலங்குகளையும், ஊர்வனவற்றையும், காட்டு விலங்குகளையும் பூமி பிறப்பிக்கக்கடவது என்றார்.  அப்படியே ஆயிற்று."
                        },
                        {
                            "V": "அப்போது கடவுள் பலவகைக் காட்டு விலங்குகளையும், வீட்டு விலங்குகளையும், பூமியின் மீது ஊர்வன யாவற்றையும் படைத்தார்.  கடவுள் அதுவும் நல்லதென்று கண்டார்."
                        },
                        {
                            "V": "பின்னர் கடவுள்: நமது சாயலாகவும் பாவனையாகவும் மனிதனைப் படைப்போமாக; அவன் கடல் மீன்களையும், வானத்துப் பறவைகளையும், மிருகங்களையும், பூமி முழுவதையும், பூமியின் மீது அசைவன ஊர்வன யாவற்றையும் ஆளக்கடவன் என்றார்."
                        },
                        {
                            "V": "இவ்வாறு கடவுள் மனிதனைத் தமது சாயலாகப் படைத்தார்.  தெய்வச் சாயலாகவே அவனைப் படைத்தார்.  ஆணும் பெண்ணுமாக அவர்களைப் படைத்தார்."
                        },
                        {
                            "V": "கடவுள் அவர்களை ஆசீர்வதித்து, நீங்கள் பலுகிப் பெருகிப் பூமியை நிரப்பி அதனைக் கீழ்ப்படுத்துங்கள்; கடல் மீன்களையும், வானத்துப் பறவைகளையும், பூமியின் மீது அசைந்து உலாவும் உயிரினங்கள் அனைத்தையும் ஆண்டு கொள்ளுங்கள் என்றார்."
                        },
                        {
                            "V": "மேலும் கடவுள்: இதோ பூமியின் மீது விதை தரும் புற்பூண்டுகள் எல்லாவற்றையும், தத்தம் இனத்தின்படி தம் விதைகளைக் கொண்டிருக்கும் விதவிதமான மரங்களையும் உங்களுக்கு உணவாகத் தந்துள்ளோம்;"
                        },
                        {
                            "V": "மேலும், பூமியில் உயிர் வாழும் விலங்குகள் வானத்தில் பறக்கும் பறவைகள், உயிரோடு பூமியில் அசையும் எல்லாவற்றிக்கும் அதே புற்பூண்டுகளை உணவாகக் கொடுத்தோம் என்றார். அதுவும் அப்படியே ஆயிற்று."
                        },
                        {
                            "V": "அப்போது கடவுள் தாம் படைத்த எல்லாவற்றையும் நோக்கினார்.  அவை எல்லாமே மிகவும் நன்றாய் இருந்தன.  மாலையும் காலையும் சேர்ந்து ஆறாம் நாள் ஆயிற்று."
                        }
                    ]
                },
                {
                    "Vs": [
                        {
                            "V": "இவ்வாறு விண்ணும் மண்ணும் அவற்றிற்கு அழகு தரும் யாவும் படைக்கப்பட்டு முடிந்தன."
                        },
                        {
                            "V": "கடவுள் தாம் ஏழாம் நாளிற்கு முன் செய்த வேலைகளையெல்லாம் முடித்து விட்டு ஏழாம் நாள் ஓய்வு எடுத்தார்."
                        },
                        {
                            "V": "மேலும் தாம் செய்ய நினைத்திருந்த வேலைகளையெல்லாம் செய்து விட்டு அந்நாளில் ஓய்வெடுத்தார்.  எனவே, அவ்வேழாம் நாளை ஆசிர்வதித்துப் பரிசுத்தமாக்கினார்."
                        },
                        {
                            "V": "இவையே விண்ணும் மண்ணும் படைக்கப் பெற்ற தொடக்கக்கால நிகழ்ச்சிகள் ஆகும்; அந்நாளில் ஆண்டவராகிய கடவுள் விண்ணையும் மண்ணையும் உண்டாக்கினார்."
                        },
                        {
                            "V": "இதற்கு முன் தரையில் இல்லாதிருந்த செடிகள் யாவற்றையும், இதற்கு முன் தரையில் வளர்ந்திராப் புற்பூண்டுகள் எல்லாவற்றையும் வயல் வெளிகளில் உண்டாக்கினார்.  உண்மையிலே அது வரை ஆண்டவராகிய கடவுள் பூமியின் மீது மழை பொழியச் செய்யவுமில்லை, நிலத்தை உழுவதற்கு ஒரு மனிதனும் இருந்ததுமில்லை."
                        },
                        {
                            "V": "ஆயினும், பூமியிலிருந்து தோன்றிய ஒரு நீருற்று பூமியெங்கும் பாய்ந்து கொண்டிருந்தது."
                        },
                        {
                            "V": "அப்படியிருக்க, ஆண்டவராகிய கடவுள் களிமண்ணால் மனிதனை உருவாக்கி, அவன் முகத்தில் உயிர் மூச்சை ஊதவே, மனிதன் உயிருள்ளவன் ஆனான்."
                        },
                        {
                            "V": "ஆண்டவராகிய கடவுள் ஆதியிலே ஓர் இன்ப வனத்தை நட்டிருந்தார்.  தாம் உருவாக்கின மனிதனை அதிலே வைத்தார்."
                        },
                        {
                            "V": "ஆண்டவராகிய கடவுள் அவ்வனத்திலே பார்வைக்கு அழகிய, நாவிற்கு இனிய கனிகள் கொண்டுள்ள பலவித மரங்களையும் மண்ணினின்று தோன்றச் செய்தார். மேலும், அந்த இன்ப வனத்தின் நடுவிலே வாழ்வளிக்கும் மரத்தையும், நன்மை தீமை அறியும் மரத்தையும் வளரச் செய்தார்."
                        },
                        {
